import json
import re
from docx import Document

TEMPLATE = 'offer_letter_template.docx'
DATA = 'employee_data.json'
OUTPUT = '/root/offer_letter_filled.docx'

with open(DATA, 'r', encoding='utf-8') as f:
    data = json.load(f)

include_relocation = str(data.get('RELOCATION_PACKAGE', '')).strip().lower() == 'yes'

start_marker = '{{IF_RELOCATION}}'
end_marker = '{{END_IF_RELOCATION}}'

pattern = re.compile(r'\{\{([A-Z_]+)\}\}')

def replace_placeholders_in_text(text: str) -> str:
    def repl(match):
        key = match.group(1)
        return str(data.get(key, match.group(0)))
    return pattern.sub(repl, text)


def process_paragraph(para):
    text = para.text
    if start_marker in text and end_marker in text:
        if include_relocation:
            new_text = text.replace(start_marker, '').replace(end_marker, '')
            new_text = replace_placeholders_in_text(new_text)
        else:
            new_text = ''
    else:
        if not pattern.search(text):
            return
        new_text = replace_placeholders_in_text(text)

    if para.runs:
        para.runs[0].text = new_text
        for run in para.runs[1:]:
            run.text = ''


def process_table(table):
    for row in table.rows:
        for cell in row.cells:
            for para in cell.paragraphs:
                process_paragraph(para)
            for nested in cell.tables:
                process_table(nested)


doc = Document(TEMPLATE)

for para in doc.paragraphs:
    process_paragraph(para)

for table in doc.tables:
    process_table(table)

for section in doc.sections:
    for para in section.header.paragraphs:
        process_paragraph(para)
    for para in section.footer.paragraphs:
        process_paragraph(para)

# Ensure conditional markers are not left behind in any paragraph (fallback)
for para in doc.paragraphs:
    if start_marker in para.text or end_marker in para.text:
        text = para.text.replace(start_marker, '').replace(end_marker, '')
        if para.runs:
            para.runs[0].text = text
            for run in para.runs[1:]:
                run.text = ''

doc.save(OUTPUT)
print(f"Wrote {OUTPUT}")
